public sealed partial class DemoWorld {
 public string EnlistQ(string side){if(side is not("Support" or "Oppose" or "Independent" or "Abstain"))return "Select an optional political path.";SystemsQ.Enlistment=side;LogQ("Voluntary enlistment / "+side);return "";}
 public string CreateTerritorySiteQ(string kind,int size=2){if(Docked||InWarp||Commander.Capsule||kind is not("Plex" or "Battlefield" or "Insurgency" or "Entosis")||size<1||size>3||Balance<500||SystemsQ.Sites.Any(s=>s.System==SystemId&&s.Kind==kind&&s.State=="Active"))return "Undock with 500 CR and choose an available local objective.";if(SystemsQ.Enlistment=="Abstain")return "Participation is optional; choose a path before deploying.";if(kind=="Entosis"&&(Current.Security>0||CorporationG==null||!HasRoleG("Director")||ItemCount("q_entosis",false)<1))return "Null security, corporation authority and owned territorial equipment required.";if(kind is "Plex" or "Battlefield"&&Current.Security>=.5)return "Militia sites require low security or local null-space adaptation.";WalletChange(-500,"Territorial operation deployment");var s=new TerritorySiteQ{System=SystemId,Cell=SolarGridKey,Anchor=SystemPosition+new SpacePosition(3000,0,0),Kind=kind,Side=SystemsQ.Enlistment,Corp=Organisations.PlayerCorp,MaxSize=size,Started=Now,Ends=Now.AddHours(1)};SystemsQ.Sites.Add(s);Bookmarks.Add(new("territory-q:"+s.Id,SystemId,"Territorial objective / "+kind,s.Anchor));BindTerritoryQ();return "";}
 public void BindTerritoryQ(){if(Docked)return;foreach(var s in SystemsQ.Sites.Where(s=>s.System==SystemId&&s.Cell==SolarGridKey&&s.State=="Active")){string node="node-q:"+s.Id+":"+s.Node;if(!Targets.Any(t=>t.Id==node))Targets.Add(new(){Id=node,Name=s.Kind+" objective node",Kind=TargetKind.Celestial,Position=(s.Anchor-SolarOrigin).Local+new Vector3(s.Node*3000,0,0),Signature=1000});if(!s.Generated){for(int i=0;i<(s.Kind=="Battlefield"?6:3);i++){var actor=MakeRaider((s.Anchor-SolarOrigin).Local+new Vector3(6000+i*500,0,800));actor.Id="q-guard:"+s.Id+":"+s.Node+":"+i;actor.Name="Territorial defense / local authored roster";actor.Training=true;s.Actors.Add(actor);}s.Generated=true;}foreach(var a in s.Actors)if(!Targets.Any(t=>t.Id==a.Id))Targets.Add(a);}}
 public void SyncTerritoryQ(){foreach(var s in SystemsQ.Sites.Where(s=>s.System==SystemId&&s.Cell==SolarGridKey&&s.State=="Active")){var live=Targets.Where(t=>t.Id.StartsWith("q-guard:"+s.Id+":")).ToArray();if(live.Length>0)s.Actors=CopyTargets(live);}}
 public string AttachSkyhookQ(string id,string planet){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==id&&s.Kind=="Skyhook"&&s.Corp==Organisations.PlayerCorp&&s.PhysicalQ);var p=SolarCatalog.ById.GetValueOrDefault(planet);if(s==null||p?.Kind!=CelestialKind.Planet||p.System!=s.System||s.PlanetQ!=""||Current.Security>0||!Organisations.Territories.Any(t=>t.System==s.System&&t.Owner==s.Corp)||Organisations.Structures.Any(q=>q.PlanetQ==planet&&q.State is not("Destroyed" or "Recovered"))||(s.AnchorQ-p.WarpPosition).Length>2500||!HasRoleG("Station Manager"))return "Owned sovereign null-space skyhook physically anchored at an unused planet required.";s.PlanetQ=planet;s.ResourceLastQ=Now;return "";}
 PlanetSourceQ? SourcePlanetQ(string celestial){string tail=celestial[(celestial.LastIndexOf(':')+1)..];return int.TryParse(tail,out int id)?PlanetsQ.ById.GetValueOrDefault(id):null;}
 public string StartSkyhookRobberyQ(string id){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==id&&s.PhysicalQ&&s.Kind=="Skyhook"&&s.State=="Online");if(s==null||Docked||s.System!=SystemId||(SystemPosition-s.AnchorQ).Length>10000||s.ShieldQ>500||s.RobberQ!=""||SourcePlanetQ(s.PlanetQ)?.Resource.Reagent==null||CombatHulls.Get(Player.CombatHull).Size<2||!LegalTheftQ(s.Corp))return "Damaged reagent silo, eligible hull, approach range and theft safety required.";s.RobberQ="player";s.RobberyStartedQ=Now;s.RobberyDropQ=false;LogQ("Observed reagent robbery begins / "+s.Id);return "";}
 public bool RobbingQ=>Organisations.Structures.Any(s=>s.RobberQ=="player"&&!s.RobberyDropQ&&s.RobberyStartedQ!=default);
 public void TickTerritoryQ(double seconds){TickStructuresQ(seconds);foreach(var s in SystemsQ.Sites.Where(s=>s.State=="Active")){if(s.Ends<=Now){s.State="Expired";continue;}if(s.System!=SystemId||s.Cell!=SolarGridKey||Docked)continue;if(Commander.Capsule||Player.Hull<=0){s.State="Failed";continue;}BindTerritoryQ();var node=Targets.First(t=>t.Id=="node-q:"+s.Id+":"+s.Node);bool hostile=Targets.Any(t=>t.Id.StartsWith("q-guard:"+s.Id+":")&&t.Alive);bool present=Vector3.Distance(Player.Position,node.Position)<=10000&&CombatHulls.Get(Player.CombatHull).Size<=s.MaxSize;bool contested=Population.Pilots.Any(p=>!p.Contracted&&p.CapsuleerQ&&p.Fit.Hull>0&&Targets.Any(t=>t.Id==p.Id&&t.Alive&&Vector3.Distance(t.Position,node.Position)<=10000));if(!present||hostile||contested||seconds<=0){SyncTerritoryQ();continue;}if(s.Kind=="Entosis"){if(Player.Cap<seconds*5||ItemCount("q_entosis",false)<1)continue;Player.Cap-=(float)seconds*5;s.FuelTimer+=seconds;while(s.FuelTimer>=120){if(ItemCount("fuel",false)<1){s.FuelTimer=120;break;}ChangeStack("fuel",false,-1);s.FuelTimer-=120;}if(s.FuelTimer>=120)continue;if(s.Warmup<60){s.Warmup=Math.Min(60,s.Warmup+seconds);continue;}}
  s.Contributions.Add("player");s.Progress=Math.Min(300,s.Progress+seconds);if(s.Progress<300){SyncTerritoryQ();continue;}if(s.Kind=="Entosis"&&s.Node<2){s.Node++;s.Progress=0;s.Warmup=0;s.Generated=false;s.Actors.Clear();Targets.RemoveAll(t=>t.Id.StartsWith("node-q:"+s.Id));BindTerritoryQ();continue;}s.State="Completed";if(s.Settled)continue;s.Settled=true;EnsureOrganisationsG();var t=Organisations.Territories.First(t=>t.System==s.System);if(s.Kind=="Entosis"){t.Owner=s.Corp;t.Attacker="";t.Capture=0;}else if(s.Kind=="Insurgency"){if(s.Side=="Support")t.Corruption=Math.Min(100,t.Corruption+25);else if(s.Side=="Oppose")t.Suppression=Math.Min(100,t.Suppression+25);else{t.Corruption=Math.Max(0,t.Corruption-10);t.Suppression=Math.Min(100,t.Suppression+10);}}else{t.MilitiaCapture=Math.Min(100,t.MilitiaCapture+25);t.Militia=s.Side;WalletChange(s.Kind=="Battlefield"?400:100,"Territorial objective reward / declared local faucet");AgentsState.Loyalty["q_local_militia"]=AgentsState.Loyalty.GetValueOrDefault("q_local_militia")+100;}LogQ("Physical territorial objective settled once / "+s.Id);}
  foreach(var h in Organisations.Structures.Where(s=>s.PhysicalQ&&s.Kind=="Skyhook"&&s.PlanetQ!="")){var p=SourcePlanetQ(h.PlanetQ);var r=p?.Resource.Reagent;if(h.ResourceLastQ==default)h.ResourceLastQ=Now;if(r!=null&&h.State=="Online"){long cycles=(long)Math.Floor(Math.Max(0,(Now-h.ResourceLastQ).TotalSeconds)/Math.Max(1,r.Cycle));h.ResourceLastQ=h.ResourceLastQ.AddSeconds(cycles*Math.Max(1,r.Cycle));decimal mature=Math.Min(h.ImmatureQ,cycles*r.Amount);h.ImmatureQ-=mature;h.MatureQ=Math.Min(r.Unsecured,h.MatureQ+mature);h.ImmatureQ=Math.Min(r.Secured,h.ImmatureQ+cycles*r.Amount);}else h.ResourceLastQ=Now;
   if(h.RobberQ=="player"&&!h.RobberyDropQ){if(Docked||SystemId!=h.System||Commander.Capsule||(SystemPosition-h.AnchorQ).Length>10000){h.RobberQ="";h.RobberyStartedQ=default;}else{Player.Velocity=Player.Velocity.Length()>1000?Vector3.Normalize(Player.Velocity)*1000:Player.Velocity;if(Now>=h.RobberyStartedQ.AddMinutes(10)){h.RobberyDropQ=true;h.RobberQ="";string item=CatalogQ.Item(r!.Type);float loot=(float)decimal.Floor((h.ImmatureQ+h.MatureQ)*.5m);Targets.Add(new(){Id="skyhook-loot-q:"+h.Id+":"+h.RobberyStartedQ.Ticks,Name="Physical reagent robbery drop",Kind=TargetKind.Container,Position=(h.AnchorQ-SolarOrigin).Local+new Vector3(1500,0,0),Contents=new(){{item,loot}},OwnerId="abandoned"});h.ImmatureQ=h.MatureQ=0;}}}
  }
  foreach(var t in Organisations.Territories){var hooks=Organisations.Structures.Where(h=>h.PhysicalQ&&h.Kind=="Skyhook"&&h.State=="Online"&&h.Corp==t.Owner&&h.System==t.System&&h.PlanetQ!="").ToArray();if(hooks.Length==0)continue;t.Power=hooks.Sum(h=>SourcePlanetQ(h.PlanetQ)?.Resource.Power??0);t.Workforce=hooks.Sum(h=>SourcePlanetQ(h.PlanetQ)?.Resource.Workforce??0);t.Commodity=hooks.Sum(h=>h.MatureQ);t.Upgrade=t.Power>=100&&t.Workforce>=100;}
 }
